function showTab(tab){document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(tab==='map'){$('welcome').classList.remove('hidden');$('mapCard').classList.remove('hidden');document.querySelectorAll('.bottom-row').forEach(x=>x.classList.remove('hidden'));return}$('welcome').classList.add('hidden');$('mapCard').classList.add('hidden');document.querySelectorAll('.bottom-row').forEach(x=>x.classList.add('hidden'));let data={army:['Army & training','RECRUIT · TRAIN · COMMAND',`<div class="stats"><div class="stat"><label>Active soldiers</label><b>${state.soldiers} troops</b></div><div class="stat"><label>Provisions</label><b>${state.food} stores</b></div><div class="stat"><label>Training</label><b>${state.level<2?'Raw recruits':'Seasoned ranks'}</b></div><div class="stat"><label>Captain</label><b>Elowen · Scout</b></div></div><p>Recruit troops for 30 gold. Scouts and veterans improve your odds in the field. Each passing season brings income, but an army consumes provisions.</p>`,`<button class="btn secondary" data-close>Close</button><button class="btn" id="trainBtn">Train · 20 gold</button><button class="btn gold" id="recruitModal">Recruit · 30 gold</button>`],court:['The royal court','POLITICS · HOUSE VALE',`The Queen's council is gathering at Alderhall. Your growing reputation may earn you a place at the table.<div class="stats"><div class="stat"><label>Your standing</label><b>${state.renown<5?'Unproven recruit':'Rising commander'}</b></div><div class="stat"><label>Royal favor</label><b>${Math.min(99,28+state.renown*4)} / 100</b></div></div><p>Serve the crown, build renown, and request a title. One day, the council may be yours to command.</p>`,`<button class="btn secondary" data-close>Return</button><button class="btn gold" id="audienceBtn">Request audience</button>`],dynasty:['House '+state.name.split(' ').pop(),'THE SEEDS OF A DYNASTY',`Your family story starts here. Bonds are built through loyalty, conversation, and deeds.<div class="person" style="background:#f6f4eb;padding:10px"><div class="avatar">👑</div><div><div class="person-name">Lady Mira of Alder</div><div class="person-role">Royal envoy · Age 24</div></div><div class="heart">♥ ${52+Math.min(40,state.renown*3)}</div></div><div class="stats"><div class="stat"><label>Intelligence</label><b>84 · Canny</b></div><div class="stat"><label>Strength</label><b>61 · Resolute</b></div><div class="stat"><label>Heart</label><b>${52+Math.min(40,state.renown*3)} · Trust</b></div><div class="stat"><label>Children</label><b>None yet</b></div></div><p>“A crown is not won by the sword alone. Tell me, commander — what would you build?”</p>`,`<button class="btn secondary" data-close>Later</button><button class="btn" id="talkLady">Share a story</button><button class="btn gold" id="courtship">Invite to court</button>`],chronicle:['Chronicle of crowns','A LIVING HISTORY',`<div class="event-list" id="modalEvents"></div><p>Every battle, alliance and heir leaves its mark upon the age.</p>`,`<button class="btn" data-close>Return to the map</button>`]}[tab];openModal(...data);if(tab==='army'){$('trainBtn').onclick=()=>{if(state.gold<20){toast('Not enough gold.');return}state.gold-=20;state.soldiers+=5;gainXP(10);log('Five soldiers completed drills with Captain Elowen.','⚔');closeModal();render();toast('Training complete.')};$('recruitModal').onclick=()=>{$('recruitBtn').click();closeModal()}}if(tab==='court')$('audienceBtn').onclick=()=>{if(state.renown>=5){gainXP(20);state.renown+=1;log(`${state.name} was granted a hearing before Queen Isolde.`,'♛');toast('The queen will remember your service.')}else toast('Win renown first: scout or claim a holding.');closeModal();render()};if(tab==='dynasty'){$('talkLady').onclick=()=>{state.renown++;gainXP(8);log('Lady Mira listened as you spoke of Greywatch and your hopes for the marches.','♥');toast('A bond begins with honest words.');closeModal();render()};$('courtship').onclick=()=>{if(state.renown>=4){state.partner=true;gainXP(20);log('Lady Mira accepted your invitation to court. A new alliance blooms.','♥');toast('A royal friendship takes root.')}else toast('Earn more renown before inviting her.');closeModal();render()}}if(tab==='chronicle'){$('modalEvents').innerHTML=state.events.slice().reverse().map(e=>`<div class="event"><div class="event-icon">${e.icon}</div><div><p>${e.text}</p><time>${e.time}</time></div></div>`).join('')||'<p>Your story is just beginning.</p>'}}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));
$('helpBtn').onclick=()=>openModal('A world waiting to be written','FIELD GUIDE · YOUR FIRST SEASON',`<b>1 · Scout.</b> Use the frontier button to reveal a nearby holding and earn renown.<br><br><b>2 · Build your banner.</b> Recruit soldiers for 30 gold. Each season brings income and provisions.<br><br><b>3 · Choose your path.</b> Challenge a small castle in battle or parley for a bloodless oath. Inspect defenders before you march.<br><br><b>4 · Write your chronicle.</b> Claim keeps, earn titles, build relationships, and pass your legacy to the next generation.<br><br><span style="font-size:11px;color:#8b9488">Tip: Battles are uncertain. A larger, experienced force has better odds. Great kingdoms are not beginner targets.</span>`);
