$('modalBack').addEventListener('click',e=>{if(e.target===$('modalBack'))closeModal()});
$('zoomIn').onclick=()=>setZoom(state.zoom+.15);$('zoomOut').onclick=()=>setZoom(state.zoom-.15);$('resetMap').onclick=()=>setZoom(1);function setZoom(z){state.zoom=Math.max(.75,Math.min(1.6,z));$('worldSvg').style.transform=`scale(${state.zoom})`;$('zoomText').textContent='MAP SCALE · '+Math.round(state.zoom*100)+'%'}
let drag=null;$('world').addEventListener('pointerdown',e=>{if(e.target.closest('.location')||e.target.closest('.map-controls'))return;drag={x:e.clientX,y:e.clientY,left:parseFloat($('worldSvg').dataset.x||0),top:parseFloat($('worldSvg').dataset.y||0)};$('world').setPointerCapture(e.pointerId)});$('world').addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;$('worldSvg').dataset.x=drag.left+dx;$('worldSvg').dataset.y=drag.top+dy;$('worldSvg').style.left=`calc(${window.innerWidth<700?'-15%':'0px'} + ${drag.left+dx}px)`;$('worldSvg').style.top=`${drag.top+dy}px`});$('world').addEventListener('pointerup',()=>drag=null);
$('modal').addEventListener('click',e=>{if(e.target.id==='saveLang'){state.language=$('languageSelect').value;closeModal();toast('Language set to '+state.language+'.')}});
// Keyboard shortcuts make the map convenient to explore.
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='+'||e.key==='=')setZoom(state.zoom+.1);if(e.key==='-')setZoom(state.zoom-.1)});
render();setTimeout(()=>{if(!localStorage.getItem('fatebearer-intro')){openModal('The marches await','A NEW CHRONICLE · SPRING 1087',`You are <b>Aren Vale</b>, an ordinary recruit in a small border kingdom. Beyond these green valleys lie three continents, a hundred great crowns, and a thousand untold stories.<br><br>Captain Elowen has marked a modest keep nearby. Scout, gather your companions, and earn your first place in history.`,`<button class="btn" id="begin">Take up your banner</button>`);$('begin').onclick=()=>{localStorage.setItem('fatebearer-intro','seen');closeModal()}}},350);
</script>
