function gainXP(n){state.xp+=n;if(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.renown+=2;state.soldiers+=5;log(`${state.name} rose to level ${state.level}. Five volunteers joined your banner.`,'⬆');toast(`LEVEL UP · You are now level ${state.level}!`)}}
 function advanceTurn(){state.turn++;state.season=(state.season+1)%4;if(state.season===0)state.year++;state.gold+=8;state.food+=5;if(state.soldiers>0)state.food-=Math.ceil(state.soldiers/40);if(state.food<0){state.food=0;state.soldiers=Math.max(1,state.soldiers-3);log('A lean winter thinned the ranks. Provisions are running low.','!')}
  if(state.turn%3===0){const rivals=holdings.filter(h=>h.owner!=='player'&&h.owner!=='independent');if(rivals.length&&Math.random()<.48){let h=rivals[Math.floor(Math.random()*rivals.length)];log(`${h.realm} has been seen mustering troops near ${h.name}.`,'⚑');}}
  render();}

input.newString:
function gainXP(n){state.xp+=n;while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.renown+=2;state.soldiers+=5;log(`${state.name} rose to level ${state.level}. Five volunteers joined your banner.`,'⬆');toast(`LEVEL UP · You are now level ${state.level}!`)}}
 function advanceTurn(){state.turn++;state.season=(state.season+1)%4;if(state.season===0){state.year++;if(state.partner&&!state.children.length&&Math.random()<.55){const childName=['Rowan','Alda','Tomas','Mira','Elian'][Math.floor(Math.random()*5)];state.children.push(childName);log(`A child, ${childName}, was born to House ${state.name.split(' ').pop()}. Your line has an heir.`,'♧');toast(`${childName} joins the family chronicle.`)}}const owned=holdings.filter(h=>h.owner==='player').length;state.gold+=8+owned*3;state.food+=5+owned*2;if(state.soldiers>0)state.food-=Math.ceil(state.soldiers/40);if(state.food<0){state.food=0;state.soldiers=Math.max(1,state.soldiers-3);log('A lean season thinned the ranks. Provisions are running low.','!')}
  if(state.turn%3===0){const rivals=holdings.filter(h=>h.owner==='hostile');if(rivals.length&&Math.random()<.48){let h=rivals[Math.floor(Math.random()*rivals.length)];log(`${h.realm} has been seen mustering troops near ${h.name}.`,'⚑');}}
  render();saveGame();}

