49: {id:'thornmere',name:'Thornmere',realm:'The Vale Marches',type:'Market town',garrison:32,owner:'independent',x:168,y:275,days:3,loot:24},
50: {id:'sunspire',name:'Sunspire',realm:'The Amber Coast',type:'Small castle',garrison:58,owner:'independent',x:278,y:158,days:4,loot:46},
