54: {id:'ravenpass',name:'Raven Pass',realm:'The Vale Marches',type:'Mountain keep',garrison:74,owner:'independent',x:178,y:120,days:5,loot:54},
55: {id:'goldenreach',name:'Golden Reach',realm:'Empire of Saffron',type:'Walled city',garrison:360,owner:'hostile',x:504,y:177,days:12,loot:150},
56: {id:'ashcourt',name:'Ashcourt',realm:'Empire of Saffron',type:'Great castle',garrison:510,owner:'hostile',x:547,y:120,days:15,loot:180},
57: {id:'ivorygate',name:'Ivory Gate',realm:'Kingdom of Kemet',type:'Desert citadel',garrison:105,owner:'hostile',x:707,y:270,days:17,loot:84},
58: {id:'jadeharbor',name:'Jade Harbor',realm:'Kingdom of Lian',type:'Coastal keep',garrison:83,owner:'independent',x:770,y:225,days:20,loot:65},
59: {id:'moonwell',name:'Moonwell',realm:'Kingdom of Lian',type:'Hill fortress',garrison:540,owner:'hostile',x:738,y:300,days:21,loot:190}
60: ];
61: let state={name:'Aren Vale',gender:'male',year:1087,season:0,gold:120,food:85,soldiers:24,renown:3,xp:40,level:1,turn:0,selected:holdings[0],quests:0,zoom:1,events:[],language:'English',scouted:[],partner:false,children:[],campaignWon:false,royalFavor:0,audience:false};
62: const seasons=['SPRING','SUMMER','AUTUMN','WINTER'];
63: const $=id=>document.getElementById(id);
64: function render(){
65:  $('date').textContent=`${seasons[state.season]} · ${state.year}`;
66:  $('heroName').textContent=state.name;$('heroRank').textContent=(state.audience?'Warden of the Marches':state.level<3?'Footsoldier':state.level<6?'Sergeant':'Banner Captain')+' · House '+(state.name.split(' ').pop()||'Vale');
67:  $('level').textContent=state.level;$('xpText').textContent=`${state.xp} / ${state.level*100} XP`;$('xpBar').style.width=Math.min(100,state.xp/(state.level*100)*100)+'%';
68:  const owned=holdings.filter(x=>x.owner==='player').length;const goldIncome=8+owned*3;const foodIncome=5+owned*2-Math.ceil(state.soldiers/40);$('gold').innerHTML=state.gold+'<span>+'+goldIncome+'</span>';$('food').innerHTML=state.food+'<span>'+(foodIncome>=0?'+':'')+foodIncome+'</span>';$('soldiers').innerHTML=state.soldiers+'<span>◈</span>';$('renown').innerHTML=state.renown+'<span>pts</span>';
69:  const h=state.selected;$('targetName').textContent=h.name;$('targetBadge').textContent=h.owner==='player'?'Your holding':h.owner==='hostile'?'Great kingdom':'Independent';$('targetMeta').textContent=h.realm+' · '+h.type;$('targetGarrison').textContent=h.owner==='player'?'Garrison secure':`${h.garrison} guards`;$('targetDistance').textContent=h.owner==='player'?'Home territory':`${h.days} days`;
70:  const ratio=h.garrison/Math.max(1,state.soldiers);$('threatText').textContent=h.owner==='player'?'Secure':ratio<1?'Favorable':ratio<2?'Even odds':ratio<5?'Difficult':'Overwhelming';$('threatBar').style.width=Math.min(100,ratio*18)+'%';$('threatBar').style.background=ratio<1?'#77966d':ratio<3?'#bd9a50':'#ad5d4f';
71:  $('attackBtn').textContent=h.owner==='player'?'Rename':h.owner==='hostile'?'⚔  Challenge':'⚔  Challenge';$('attackBtn').disabled=h.owner==='hostile'&&state.soldiers<Math.min(45,h.garrison*.35);
72:  $('targetCount').textContent=String(holdings.indexOf(h)+1).padStart(2,'0')+' / '+String(holdings.length).padStart(2,'0');
73:  updateQuest();
74:  $('portrait').textContent=state.gender==='male'?'🧑🏻‍🌾':'👩🏽‍🌾';
75:  drawMap();drawEvents();checkCampaign();
76: }
77: function updateQuest(){const owned=holdings.filter(h=>h.owner==='player').length;const stage=owned>=5?4:state.audience?3:state.soldiers>=44?2:(state.scouted&&state.scouted.length)||owned?1:0;state.quests=stage;const missions=[['Scout the frontier','Scout a nearby holding to learn the lay of the land. Every legend begins with a small victory.'],['Gather your banner','Raise a levy to bring your company to at least 44 soldiers.'],['A voice in the council','Earn 5 renown, then request an audience with Queen Isolde.'],['Unite the Vale','Claim 5 holdings by battle or parley to secure the marches.'],['A realm remembered','The Vale is united. Continue your chronicle, build your dynasty, and seek the crowns beyond.']];$('questEyebrow').textContent=stage===4?'✦ First steps · complete':'✦ First steps · mission '+(stage+1)+' / 4';$('questTitle').textContent=missions[stage][0];$('questText').textContent=missions[stage][1];$('questCount').textContent=stage===4?'4 / 4':stage+' / 4';$('questBar').style.width=(stage*25)+'%'}
78:  function checkCampaign(){if(!state.campaignWon&&holdings.filter(h=>h.owner==='player').length>=5){state.campaignWon=true;log(`${state.name} united the Vale Marches beneath one banner.`,'♛');openModal('The Vale is united','CAMPAIGN MILESTONE · 5 HOLDINGS',`The marches answer to your banner. This is only the first chapter: keep building your realm, seek alliances, and prepare for the crowns beyond the Vale.<div class="stats"><div class="stat"><label>Holdings</label><b>${holdings.filter(h=>h.owner==='player').length} / ${holdings.length}</b></div><div class="stat"><label>Renown</label><b>${state.renown}</b></div><div class="stat"><label>House</label><b>${state.name.split(' ').pop()}</b></div></div>`,`<button class="btn gold" data-close>Continue the chronicle</button>`);saveGame()}}
79:  function drawMap(){const group=$('locations');group.innerHTML='';holdings.forEach(h=>{let g=document.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('class','location'+(state.selected.id===h.id?' selected':''));g.setAttribute('transform',`translate(${h.x},${h.y})`);g.innerHTML=`<circle r="${state.selected.id===h.id?8:6}" fill="${h.owner==='player'?'#557d59':h.owner==='hostile'?'#a75043':'#b68d43'}"></circle><text x="10" y="3">${h.name}</text>`;g.addEventListener('click',e=>{e.stopPropagation();state.selected=h;render()});group.appendChild(g)});
80: }
81: function drawEvents(){const list=$('eventList');list.innerHTML='';const items=state.events.slice(-3).reverse();if(!items.length){items.push({icon:'♜',text:'Kingdoms of the Known World gather beneath their banners.',time:`${seasons[state.season]} · ${state.year}`},{icon:'✉',text:'A royal courier arrives with word from the capital.',time:'3 DAYS AGO'})}items.forEach(e=>{let el=document.createElement('div');el.className='event';el.innerHTML=`<div class="event-icon">${e.icon}</div><div><p>${e.text}</p><time>${e.time}</time></div>`;list.appendChild(el)})}
82: function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2500)}
83: function log(text,icon='✦'){state.events.push({icon,text,time:`${seasons[state.season]} · ${state.year}`});drawEvents()}
84: function gainXP(n){state.xp+=n;while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.renown+=2;state.soldiers+=5;log(`${state.name} rose to level ${state.level}. Five volunteers joined your banner.`,'⬆');toast(`LEVEL UP · You are now level ${state.level}!`)}}
85: function advanceTurn(){state.turn++;state.season=(state.season+1)%4;if(state.season===0){state.year++;if(state.partner&&!state.children.length&&Math.random()<.55){const childName=['Rowan','Alda','Tomas','Mira','Elian'][Math.floor(Math.random()*5)];state.children.push(childName);log(`A child, ${childName}, was born to House ${state.name.split(' ').pop()}. Your line has an heir.`,'♧');toast(`${childName} joins the family chronicle.`)}}const owned=holdings.filter(h=>h.owner==='player').length;state.gold+=8+owned*3;state.food+=5+owned*2;if(state.soldiers>0)state.food-=Math.ceil(state.soldiers/40);if(state.food<0){state.food=0;state.soldiers=Math.max(1,state.soldiers-3);log('A lean winter thinned the ranks. Provisions are running low.','!')}
86:  if(state.turn%3===0){const rivals=holdings.filter(h=>h.owner==='hostile');if(rivals.length&&Math.random()<.48){let h=rivals[Math.floor(Math.random()*rivals.length)];log(`${h.realm} has been seen mustering troops near ${h.name}.`,'⚑');}}
87:  render();saveGame();}
88: function openModal(title,subtitle,body,actions){$('modal').innerHTML=`<div class="eyebrow">${subtitle||'FATEBEARER · CHRONICLE OF CROWNS'}</div><h2>${title}</h2><div class="modal-body">${body}</div><div class="modal-actions">${actions||'<button class="btn" data-close>Continue</button>'}</div>`;$('modalBack').classList.add('open');$('modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}
89: function closeModal(){$('modalBack').classList.remove('open')}
90: function attack(){const h=state.selected;if(h.owner==='player'){renameHolding();return}if(state.soldiers<Math.max(12,Math.floor(h.garrison*.22))){toast('Gather more soldiers before marching.');return}
