const sleep=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{
 const tabs=await (await fetch('http://127.0.0.1:9222/json')).json();
 const page=tabs.find(x=>x.type==='page'); if(!page) throw Error('No browser page');
 const ws=new WebSocket(page.webSocketDebuggerUrl); let next=0, pending=new Map();
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
 await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
 const send=(method,params={})=>new Promise(resolve=>{const id=++next;pending.set(id,resolve);ws.send(JSON.stringify({id,method,params}))});
 const evaluate=async expression=>{const m=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(m.error)throw Error(JSON.stringify(m.error));if(m.result.exceptionDetails)throw Error(m.result.exceptionDetails.text);return m.result.result.value};
 await send('Runtime.enable'); await sleep(900);
 console.log('intro:',await evaluate("document.querySelector('#modal h2')?.textContent"));
 await evaluate("document.querySelector('#begin')?.click()");
 await evaluate("document.querySelector('#seasonBtn').click()");
 console.log('season:',await evaluate("document.querySelector('#date').textContent"));
 await evaluate("state.renown=5;document.querySelector('[data-tab=court]').click();document.querySelector('#audienceBtn').click()");
 console.log('court reward:',await evaluate("JSON.stringify({audience:state.audience,rank:document.querySelector('#heroRank').textContent,quest:document.querySelector('#questTitle').textContent,favor:state.royalFavor})"));
 await evaluate("document.querySelector('[data-tab=dynasty]').click();document.querySelector('#courtship').click();Math.random=()=>0;for(let i=0;i<4;i++)document.querySelector('#seasonBtn').click();document.querySelector('[data-tab=dynasty]').click()");
 console.log('dynasty:',await evaluate("JSON.stringify({partner:state.partner,children:state.children,text:document.querySelector('.modal-body .stats').textContent})"));
 console.log('saved:',await evaluate("!!localStorage.getItem('fatebearer-save')"));
 ws.close();
})().catch(e=>{console.error(e);process.exit(1)});
